package main

import (
	"bufio"
	"fmt"
	"os"
)

var n int64
var seen map[int64]bool

func gen(cur int64, x, y int64) {
	if cur > n {
		return
	}
	if cur > 0 {
		seen[cur] = true
	}
	if !(cur == 0 && x == 0) {
		nx := cur*10 + x
		if nx > cur {
			gen(nx, x, y)
		}
	}
	if x != y {
		if !(cur == 0 && y == 0) {
			ny := cur*10 + y
			if ny > cur {
				gen(ny, x, y)
			}
		}
	}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	fmt.Fscan(reader, &n)
	seen = make(map[int64]bool)
	for x := int64(0); x <= 9; x++ {
		for y := x; y <= 9; y++ {
			gen(0, x, y)
		}
	}
	fmt.Println(len(seen))
}
